"Tu suscripción sigue pagada hasta el {fecha}, pero cancelaste la renovación: los beneficios Orbit están desactivados desde ahora.":"あなたのサブスクリプションは {fecha} まで支払い済みですが、更新をキャンセルしたため、Orbit の特典は今から無効になります。",
"Tu suscripción sigue pagada, pero cancelaste la renovación: los beneficios Orbit están desactivados desde ahora.":"サブスクリプションは支払い済みですが、更新をキャンセルしたため、Orbit の特典は現在から無効になっています。",
