"Tu sesión es válida, pero no encontramos tu perfil. Complétalo aquí para activar tu cuenta.":"セッションは有効ですが、あなたのプロフィールが見つかりませんでした。アカウントを有効にするには、こちらで入力を完了してください。",
"Tu cuenta necesita un nombre de usuario para continuar. Elige el tuyo en el siguiente paso.":"続けるには、アカウントにユーザー名が必要です。次のステップで選んでください。",
"A tu cuenta le faltan algunos datos. Complétalos aquí para entrar.":"アカウントに不足している情報があります。ここで入力して入室してください。",
"No pudimos recuperar tu sesión automáticamente. Revisa tu conexión e inicia sesión de nuevo.":"セッションを自動で復元できませんでした。接続を確認して再度ログインしてください。",
