"Ver destello de":"さんのグリマーを見る",
"Publicación de":"投稿者：",
"Los destellos desaparecen a las 5 horas. Toca el bot\\u00f3n de abajo para ser la primera persona en compartir uno.":"グリマーは5時間で消えます。下のボタンをタップして、最初にシェアする人になりましょう。",
"No se pudo abrir el chat. Int\\u00e9ntalo de nuevo.":"チャットを開けませんでした。もう一度お試しください。",
"Volver\\u00e1s a ver sus destellos":"再びその人のグリマーが表示されます",
"Ya no ver\\u00e1s sus destellos":"その人のグリマーはもう表示されません",
"Nuevo inicio de sesi\\u00f3n":"新しいログイン",
"\\u00bfCerrar esta sesi\\u00f3n de Drex?":"このDrexセッションを閉じますか？",
