"Adjunta la foto con el botón de imagen del compositor de Baro y repite tu mensaje, por ejemplo: «cambia mi foto de perfil».":"Baroのコンポーザーの画像ボタンで写真を添付して、メッセージをもう一度送ってください。例：「プロフィール写真を変更して」。",
"Adjunta la imagen con el botón de imagen del compositor de Baro y repite tu mensaje, por ejemplo: «cambia mi portada».":"Baroのコンポーザーの画像ボタンで画像を添付して、メッセージをもう一度送ってください。例：「カバーを変更して」。",
"Ahí cambias idioma, notificaciones, privacidad y tu suscripción.":"そこで言語、通知、プライバシー、サブスクリプションを変更できます。",
