"Aún no existe una forma de invitar usuarios a las salas de voz en la app: las salas de voz se comparten por su nombre y cada quien se une desde su tarjeta.":"アプリにはまだボイスルームへユーザーを招待する方法がありません。ボイスルームは名前で共有され、各自がカードから参加します。",
"Aún no hay nada que guardar: conversa primero con Baro.":"まだ保存するものがありません。まずBaroと会話してください。",
"Aún no tienes historial de votos: te muestro lo más votado de la comunidad.":"まだ投票履歴がありません。コミュニティで最も投票されたものを表示します。",
"Baro aún no puede recibir archivos de audio: el compositor solo admite fotos. Para subir tu canción abre la sección Música y usa «Subir canción».":"Baroはまだ音声ファイルを受け取れません。コンポーザーは写真のみ対応です。曲をアップロードするには音楽セクションを開いて「曲をアップロード」を使ってください。",
