"No pude mostrar la confirmación ahora mismo.":"今は確認を表示できませんでした。",
"No pude procesar la imagen. Prueba con otra más pequeña.":"画像を処理できませんでした。もっと小さい画像でお試しください。",
"No pude sacarte de la sala de voz. Inténtalo de nuevo.":"ボイスルームから退出させられませんでした。もう一度お試しください。",
"No pude unirte a la sala de voz. Inténtalo de nuevo.":"ボイスルームに参加させられませんでした。もう一度お試しください。",
"No puedo abrir el editor desde aquí. Abre «Mis borradores» en la app y toca el borrador.":"ここからエディタを開けません。アプリで「下書き」を開いて下書きをタップしてください。",
"No se pudo abrir el borrador. Inténtalo de nuevo.":"下書きを開けませんでした。もう一度お試しください。",
"No se pudo actualizar el grupo. Inténtalo de nuevo.":"グループを更新できませんでした。もう一度お試しください。",
"No se pudo actualizar la lista. Inténtalo de nuevo.":"リストを更新できませんでした。もう一度お試しください。",
"No se pudo cambiar el nombre de usuario (puede estar en uso o dentro del periodo de 7 días).":"ユーザー名を変更できませんでした（使用中の可能性、または7日間の制限期間内の可能性があります）。",
"No se pudo pedir la confirmación.":"確認をリクエストできませんでした。",
"No supe convertir eso en pasos. Dime qué botón toco o qué campo lleno.":"それを手順に変換できませんでした。どのボタンを押すか、どの欄に入力するか教えてください。",
"No sé a qué post te refieres. Pásame el enlace (#/post/…) o descríbelo (\"ese\", \"el de ayer\").":"どの投稿か分かりません。リンク（#/post/…）を送るか説明してください（「あれ」「昨日の」など）。",
"No sé a qué post te refieres. Pásame el enlace o descríbelo.":"どの投稿か分かりません。リンクを送るか説明してください。",
"No sé en qué pantalla estás, pero pregúntame lo que sea.":"今どの画面にいるか分かりませんが、何でも聞いてください。",
"No tienes hilos guardados. Di «guarda este hilo» cuando quieras conservar una investigación.":"保存したスレッドがありません。調査を残したいときは「このスレッドを保存して」と言ってください。",
"No tienes rutinas guardadas. Dime por ejemplo: «crea mi rutina de mañana: revisa notificaciones, dime qué pasó hoy».":"保存したルーティンがありません。例：「朝のルーティンを作って：通知を確認して、今日何があったか教えて」。",
"No tienes vigilantes activos. Dime por ejemplo: «avísame cuando tenga un seguidor nuevo».":"有効なウォッチャーがありません。例：「新しいフォロワーがついたら知らせて」。",
"No veo nada cargado: la pantalla parece vacía.":"何も読み込まれていません：画面は空のようです。",
"Nota: los vigilantes funcionan mientras Drex está abierto en este dispositivo.":"注：ウォッチャーはこのデバイスでDrexが開いている間だけ動作します。",
"O escríbela como quieras: «mañana a las 9», «el lunes», «en 3 horas».":"または自由に書いてください：「明日の9時」「月曜日」「3時間後」。",
"Perfil atualizado.":"プロフィールを更新しました。",
"Permisos del sistema (cámara, notificaciones): los apruebas tú.":"システムの許可（カメラ、通知）はあなたが承認します。",
"Plan cancelado. Nada se ejecutó.":"プランをキャンセルしました。何も実行されていません。",
"Planificando la investigación…":"調査を計画中…",
"Por lo que veníamos hablando, ¿quisiste decir…?":"これまでの話からすると、もしかして…？",
"Primero acepta los Términos de música en la sección Música (con tu nombre de artista). Después podrás subir canciones con Baro.":"まず音楽セクションで音楽の利用規約に同意してください（アーティスト名で）。その後Baroで曲をアップロードできます。",
"Prueba con saludos y frases comunes como «hola», «gracias» o «¿cómo estás?».":"「hola」「gracias」「¿cómo estás?」のような挨拶やよく使うフレーズで試してみてください。",
"Pásame el texto que quieres resumir.":"要約したいテキストを送ってください。",
"Pídeme «busca en vivos de …» y te digo qué hay ahora mismo.":"「…のライブを探して」と言えば、今何があるか教えます。",
"Pídeme «busca fiestas de …» y te encuentro las que estén activas.":"「…のパーティーを探して」と言えば、開催中のものを見つけます。",
"Pídeme «busca …» y rastreo posts, comentarios, perfiles, música y votaciones.":"「…を探して」と言えば、投稿、コメント、プロフィール、音楽、投票を検索します。",
"Revisa el plan y toca Ejecutar. Nada público se hará sin tu confirmación por paso.":"プランを確認して実行をタップしてください。各ステップの確認なしに公開されることはありません。",
"Revisa el plan y toca Ejecutar. Nada se hará sin tu toque.":"プランを確認して実行をタップしてください。あなたのタップなしには何も実行されません。",
"Revisa el resumen y toca Confirmar para crear el grupo.":"要約を確認して「確認」をタップするとグループが作成されます。",
"Revisa y toca Confirmar para quitar la fijación.":"確認して「確認」をタップするとピン留めが解除されます。",
"Revisando la traducción…":"翻訳を確認中…",
"Se abrió el formulario de reporte. Elige el motivo y envíalo para completar el reporte.":"通報フォームが開きました。理由を選んで送信すると通報が完了します。",
"Se gerencia em Ajustes → Drex Orbit.":"設定 → Drex Orbit で管理できます。",
"Sintetizando o relatório…":"レポートを作成中…",
"Sobre o que é o modelo? Escreve assim: \"/plantilla anuncio meu evento\".":"テンプレートのテーマは何ですか？こう書いてください：「/plantilla anuncio 私のイベント」。",
"Solicitaste eliminar tu cuenta. ¿Quieres cancelar la eliminación y reactivarla ahora?":"アカウント削除をリクエスト済みです。削除をキャンセルして今すぐ再有効化しますか？",
